@If (PDesc = ""; @Return(@Do(@Command([EditGotoField];"PDesc") ;@Prompt([Ok];"Missing Value"; "Non-conformance Description must be entered before proceeding!")));"");

FIELD DateSent := @Today;
FIELD CurrentAction := "Reply";
