@If ((Comment1 = "" & ComDate1 = "") | (Comment1 != "" & ComDate1 != "");""; @Return(@Do(@Command([EditGotoField];"Comment1") ;@Prompt([Ok]; "Missing Value"; "Please fill in all data for Comment 1"))));
